server {
    listen 8080;
    server_name _;

    location = / {
      root /gallery;
      try_files /index.html =404;
    }

    location ^~ /images/ {
      alias /images/;
      autoindex on;
      autoindex_exact_size off;
      autoindex_localtime on;

      expires 30d;
      add_header Cache-Control "public, immutable, no-store";

      include /etc/nginx/mime.types;
      default_type application/octet-stream;
      index off;
    }
}
